import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int rows = nextInt(), cols = nextInt();
        String[] board = new String[rows];
        for (int i = 0; i < rows; i++) board[i] = next();
        int bottom = 0;
        for (int i = 0; i < rows; i++)
            if (board[i].indexOf('*') >= 0) bottom = i;
        int distance = rows - 1 - bottom;
        long answer = 0;
        // Each '*' sweeps rows i+1..i+distance of its column; merge with a difference array.
        for (int j = 0; j < cols; j++) {
            int[] diff = new int[rows + 1];
            for (int i = 0; i < rows; i++)
                if (board[i].charAt(j) == '*') {
                    diff[i + 1]++;
                    diff[i + distance + 1]--;
                }
            int active = 0;
            for (int i = 0; i < rows; i++) {
                active += diff[i];
                if (active != 0 && board[i].charAt(j) == '#') answer++;
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strings"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	rows, cols := int(nextInt()), int(nextInt())
	board := make([]string, rows)
	for i := range board {
		board[i] = next()
	}
	bottom := 0
	for i := 0; i < rows; i++ {
		if strings.IndexByte(board[i], '*') >= 0 {
			bottom = i
		}
	}
	distance := rows - 1 - bottom
	answer := 0
	// Each '*' sweeps rows i+1..i+distance of its column; merge with a difference array.
	for j := 0; j < cols; j++ {
		diff := make([]int, rows+1)
		for i := 0; i < rows; i++ {
			if board[i][j] == '*' {
				diff[i+1]++
				diff[i+distance+1]--
			}
		}
		active := 0
		for i := 0; i < rows; i++ {
			active += diff[i]
			if active != 0 && board[i][j] == '#' {
				answer++
			}
		}
	}
	fmt.Println(answer)
}
